-- Replace the legacy three-table crafting catalog with the JSON recipe catalog.
-- 562 canonical recipes imported from habbo_recipes_updated.json.
-- Recipe IDs are regenerated sequentially for this JSON-only catalog; no legacy recipe rows or metadata are retained.
-- station_ids is JSON because the source pages do not always map one-to-one to a server altar.
-- Four duplicate product records in the source were canonicalized because the server identifies a recipe by product_name.
-- Recipes without a known legacy station keep station_ids=[] and remain catalogued until their server station is mapped.
DROP TABLE IF EXISTS `crafting_altars_recipes`;
DROP TABLE IF EXISTS `crafting_recipes_ingredients`;
DROP TABLE IF EXISTS `crafting_recipes`;

CREATE TABLE `crafting_recipes` (
  `id` int(11) NOT NULL,
  `source_page` int(11) NOT NULL DEFAULT 0,
  `source_url` varchar(255) NOT NULL DEFAULT '',
  `product_name` varchar(64) NOT NULL,
  `reward_name` varchar(64) NOT NULL,
  `station_ids` JSON NOT NULL,
  `ingredients` JSON NOT NULL,
  `enabled` enum('0','1') NOT NULL DEFAULT '1',
  `achievement` varchar(255) NOT NULL DEFAULT '',
  `secret` enum('0','1') NOT NULL DEFAULT '0',
  `limited` enum('0','1') NOT NULL DEFAULT '0',
  `remaining` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_name` (`product_name`),
  KEY `source_page` (`source_page`),
  KEY `enabled` (`enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM `users_recipes`;
